-- Adds the generic content-translation infrastructure: a single translation-memory table
-- keyed by (entity_type, entity_id, locale) rather than one column per language, so adding
-- a new language never requires a schema change (see ContentTranslation.java and
-- TranslationService.java), plus the human-reviewed Hebrew seed translations for all
-- catalog/recipe content (source=HUMAN), so the app's first impression in Hebrew is
-- polished rather than relying on live machine translation.

-- IETF language tag a recipe's title/description/ingredients/instructions were authored
-- in. Existing rows were all seeded in English.
ALTER TABLE recipes ADD COLUMN source_locale VARCHAR(10) NOT NULL DEFAULT 'en';

CREATE TABLE IF NOT EXISTS content_translations (
    id VARCHAR(36) NOT NULL PRIMARY KEY,
    entity_type VARCHAR(40) NOT NULL,
    entity_id VARCHAR(36) NOT NULL,
    locale VARCHAR(10) NOT NULL,
    value TEXT NOT NULL,
    source VARCHAR(20) NOT NULL,
    updated_at DATETIME NOT NULL,
    CONSTRAINT uk_content_translation_target UNIQUE (entity_type, entity_id, locale)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

