INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'סלט חצילים כבושים מזרח תיכוני תוסס: פרוסות חציל דקות מטוגנות (או אפויות) עד להזהבה, ואז מסודרות בשכבות עם כבישה של שמן זית עם שום, חומץ ולימון, עמוסה בפטרוזיליה טרייה. הכי טוב אחרי שעות מנוחה, אבל לרוב לא שורד כל כך הרבה זמן.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = '0ea015b7-a69e-4e93-a9c5-874f06a047b4' AND db.type = 'TEXT' AND db.text = 'A vibrant Middle Eastern pickled eggplant salad: thin eggplant slices fried (or baked) until golden, then layered with a garlicky olive oil, vinegar, and lemon pickle brimming with fresh parsley. It''s best after resting a few hours, but it rarely lasts that long.';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'קארי חלב קוקוס ריחני עם רצועות עוף רכות, חציל תאילנדי, נבטי במבוק, ועלי בזיליקום תאילנדי מתוק וטרי.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = '142c152b-0fff-4133-9f1c-564da0b5b411' AND db.type = 'TEXT' AND db.text = 'A fragrant coconut milk curry with tender chicken strips, Thai eggplant, bamboo shoots, and fresh sweet Thai basil leaves.';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'עקבו אחר ההוראות המפורטות למטה לחוויית בישול הטובה ביותר. בישול מהנה!', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = '142c152b-0fff-4133-9f1c-564da0b5b411' AND db.type = 'TEXT' AND db.text = 'Follow the detailed instructions below for the best culinary experience. Enjoy cooking!';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'מרק עצמות בקר מתובל וריחני שמתבשל 12 שעות, מוגש על אטריות אורז, פרוסות דקות של בקר גולמי (Eye Round), בזיליקום טרי ונבטי שעועית.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = '1868adb5-a11b-43d8-aece-e84db8fa2110' AND db.type = 'TEXT' AND db.text = 'A aromatic 12-hour spiced beef bone broth poured over rice noodles, thinly sliced raw eye round beef, fresh basil, and bean sprouts.';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'עקבו אחר ההוראות המפורטות למטה לחוויית בישול הטובה ביותר. בישול מהנה!', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = '1868adb5-a11b-43d8-aece-e84db8fa2110' AND db.type = 'TEXT' AND db.text = 'Follow the detailed instructions below for the best culinary experience. Enjoy cooking!';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'לחם שטוח ללא גלוטן העשוי מאורז, קינואה, עדשים ושעועית מש שהושרו והותססו — נטחנים לבלילה, נאפים דק, ומתובלים בזעתר, קצח, שומשום או זרעי כמון. לא באמת פיתה, אלא תחליף מזין ועתיר חלבון.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = '20d15ac3-a89c-4115-ba21-2d3447105f38' AND db.type = 'TEXT' AND db.text = 'A gluten-free flatbread made from soaked, fermented rice, quinoa, lentils, and mung beans — blended into a batter, baked thin, and topped with za''atar, nigella, sesame, or cumin seeds. Not actually pita, but a nourishing, protein-rich stand-in.';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'טונה אהי צרובה בציפוי שומשום מעל אורז לסושי עם מנגו, מלפפון, אדממה, אבוקדו וניגוב מיונז סריראצ''ה חריף.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = '261a09eb-c028-43e0-ae38-5f815ff96e67' AND db.type = 'TEXT' AND db.text = 'Sesame-crusted seared Ahi tuna over sushi rice with mango, cucumber, edamame, avocado, and spicy sriracha mayo drizzle.';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'עקבו אחר ההוראות המפורטות למטה לחוויית בישול הטובה ביותר. בישול מהנה!', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = '261a09eb-c028-43e0-ae38-5f815ff96e67' AND db.type = 'TEXT' AND db.text = 'Follow the detailed instructions below for the best culinary experience. Enjoy cooking!';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'פרוסת מחמצת קלויה עם אבוקדו מרוסק ולימון, מוגשת עם ביצה פושה נוזלית, צנוניות ופתיתי פלפל אדום.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = '26b0c2da-12dd-4e64-a871-a65dc70ad6c7' AND db.type = 'TEXT' AND db.text = 'Artisan toasted sourdough spread with smashed lemon avocado, topped with a runny poached egg, radishes, and red pepper flakes.';
