INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'תערובת עבה ותוססת של אסאי קפוא ופירות יער, מתובלת בזרעי צ''יה, פרוסות בננה, שבבי קוקוס קלויים וגרנולה פריכה.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = '2bb704e1-955d-4c0a-bfc5-25e3fc2872ef' AND db.type = 'TEXT' AND db.text = 'Thick vibrant frozen acai and wild berry blend topped with chia seeds, sliced bananas, toasted coconut flakes, and crunchy granola.';
