INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'אורז זעפרן ולנסיאני מסורתי עם שרימפס ג''מבו, צדפות, טבעות קלמארי, פלפלים אדומים ואפונה.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = '2ccb4de6-3b95-437d-a540-37ade62e0be1' AND db.type = 'TEXT' AND db.text = 'Traditional Valencian saffron rice studded with jumbo shrimp, mussels, calamari rings, red bell peppers, and peas.';
