INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'עוגיות שוקולד מריר עשירות עם מרכז שוקולד נוזלי חם, מפוזרות באבקת סוכר וגלידת וניל.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = '31835cec-ba46-452c-a2d2-1e69502481f6' AND db.type = 'TEXT' AND db.text = 'Rich dark chocolate cakes baked with a warm, gooey liquid chocolate center, dusted with powdered sugar and vanilla ice cream.';
