INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'תבשיל אלפיני צרפתי עשיר של תפוחי אדמה פרוסים, קוביות בייקון מעושנות ובצל מקורמל, מכוסה בגבינת רבלושון מומסת.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = '3c1e26ca-59fa-408a-8df2-bc408fba42ab' AND db.type = 'TEXT' AND db.text = 'A decadent French Alpine casserole of sliced potatoes, smoky bacon lardons, and caramelized onions smothered in melted Reblochon cheese.';
