INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'לבבות חסה רומית פריכים בתוספת רוטב קיסר קרמי עם אנשובי ושום, קרוטוני שום ומחמצת פריכים, פרמזן מגורד דק ועוף על האש.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = '484d779c-dbaf-4e82-b7d5-c7e5f51bf6da' AND db.type = 'TEXT' AND db.text = 'Crisp Romaine lettuce hearts tossed in creamy anchovy-garlic Caesar dressing, crunchy garlic sourdough croutons, shaved Parmesan, and grilled chicken.';
