INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'עוגת קרנץ שמרים מגולגלת ומפותלת — כמו בבקה — העשויה מבצק ללא לישה שלא מסבך. במקום בצק מודבק אמיתי, הבצק מרודד וממולא פעמיים כדי לבנות שכבות דקות עם הרבה מילוי, ואז מפותל לצמה ונאפה. המתכון הזה מכין שני כיכרות: אחת עם מילוי שוקולד עשיר, והשנייה עם חמאת בוטנים וריבה, שתיהן נמרחות בסירופ סוכר ישר מהתנור.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = 'adefaece-50fb-439d-816a-2790342c7d1d' AND db.type = 'TEXT' AND db.text = 'A rolled, twisted yeasted kranz cake — like a babka — made from a fuss-free no-knead dough. Instead of true laminated dough, the dough is rolled and filled twice to build thin layers with plenty of filling, then twisted into a braid and baked. This recipe makes two loaves: one with a rich chocolate filling, the other with peanut butter and jam, both brushed with sugar syrup straight out of the oven.';
