INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'ביצים פושה ברוטב עגבניות, פלפלים ושום עשיר ומבושל, מתובל בכמון ופפריקה מעושנת, מכוסה בפטה מפוררת.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = 'c15e7c29-b6ed-4728-a652-4321527abf64' AND db.type = 'TEXT' AND db.text = 'Poached eggs in a rich simmered tomato, bell pepper, and garlic sauce spiced with cumin and smoked paprika, topped with crumbled feta.';
