INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'קרקרים ללא גלוטן העשויים משיבולת שועל וזרעים — פשוטים להכנה, פריכים להפליא, ונשמרים היטב בכלי אטום עד שבועיים.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = 'd6162e6e-1ce4-4a5e-91d1-6754926f814d' AND db.type = 'TEXT' AND db.text = 'Gluten-free crackers made with oats and seeds — simple to prepare, wonderfully crispy, and they keep beautifully in a sealed container for up to two weeks.';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'חלת שבת קלה, אווררית וטעימה, בהדרכה שלב אחר שלב. היא דורשת קצת יותר מאמץ ממתכון מהיר טיפוסי, אבל נשארת פשוטה וניתנת לניהול — והגרסה עם שמרים טריים יוצאת קלילה וטעימה במיוחד.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = 'd63b981b-1417-4b97-8c13-3f767398858a' AND db.type = 'TEXT' AND db.text = 'An easy, airy, and delicious Shabbat challah, walked through step by step. It takes a little more effort than a typical quick recipe, but stays simple and manageable — and the fresh-yeast version comes out especially light and flavorful.';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'קוביות טופו שומשום פריכות מוגשות מעל קינואה עם כרוב סגול, אדממה, גזר מגורר ורוטב בוטנים-ג''ינג''ר קרמי.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = 'd6802a63-c533-4681-990e-bb64664db63b' AND db.type = 'TEXT' AND db.text = 'Pan-crisped sesame tofu cubes served over quinoa with purple cabbage, edamame, shredded carrots, and creamy peanut ginger sauce.';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'עקבו אחר ההוראות המפורטות למטה לחוויית בישול הטובה ביותר. בישול מהנה!', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = 'd6802a63-c533-4681-990e-bb64664db63b' AND db.type = 'TEXT' AND db.text = 'Follow the detailed instructions below for the best culinary experience. Enjoy cooking!';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'אורז ארבוריו איטלקי המבושל לאט תוך ערבוב בציר ירקות טעים, מסתיים בפטריות פורצ''יני מוקפצות, חמאה ופרמג''אנו-רג''אנו.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = 'de2d322c-e552-4016-8539-a12dbb718832' AND db.type = 'TEXT' AND db.text = 'Slow-stirred Italian Arborio rice cooked in savory vegetable stock, finished with sautéed porcini mushrooms, butter, and Parmigiano-Reggiano.';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'עקבו אחר ההוראות המפורטות למטה לחוויית בישול הטובה ביותר. בישול מהנה!', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = 'de2d322c-e552-4016-8539-a12dbb718832' AND db.type = 'TEXT' AND db.text = 'Follow the detailed instructions below for the best culinary experience. Enjoy cooking!';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'עוגת גבינה אפויה סמיכה וקרמית במיוחד עם בסיס פירורי ביסקוויטים חמאתי, נאפית לאט ומכוסה ברוטב פטל טרי.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = 'e09a50a9-ffd9-4983-b75d-4a7877bdd78c' AND db.type = 'TEXT' AND db.text = 'Dense, ultra-cremy baked cheesecake with a buttery Graham cracker crust, baked slowly and topped with fresh raspberry coulis.';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'עקבו אחר ההוראות המפורטות למטה לחוויית בישול הטובה ביותר. בישול מהנה!', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = 'e09a50a9-ffd9-4983-b75d-4a7877bdd78c' AND db.type = 'TEXT' AND db.text = 'Follow the detailed instructions below for the best culinary experience. Enjoy cooking!';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'טורטיות תירס חמות מכוסות בביצים מטוגנות עין, סלסת ראנצ''רו עגבניות קלויות תוצרת בית, שעועית מרוסקת ואבוקדו.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = 'f5a9c699-8b80-490f-83f6-b47aa957df46' AND db.type = 'TEXT' AND db.text = 'Warm corn tortillas topped with fried sunny-side-up eggs, homemade roasted tomato ranchero salsa, refried beans, and avocado.';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'עקבו אחר ההוראות המפורטות למטה לחוויית בישול הטובה ביותר. בישול מהנה!', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = 'f5a9c699-8b80-490f-83f6-b47aa957df46' AND db.type = 'TEXT' AND db.text = 'Follow the detailed instructions below for the best culinary experience. Enjoy cooking!';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'שני קציצות בקר מעוכות ופריכות, גבינה אמריקאית נמסה, בצל מקורמל, חמוצים ורוטב המבורגר ביתי עשיר על בריוש קלוי.', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = 'f8c7c0e5-ed02-4070-8e8f-eb57e9f06e91' AND db.type = 'TEXT' AND db.text = 'Two crispy smashed beef patties, melted American cheese, caramelized onions, pickles, and tangy homemade burger sauce on toasted brioche.';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) SELECT UUID(), 'RECIPE_DESCRIPTION_BLOCK', db.id, 'he', 'עקבו אחר ההוראות המפורטות למטה לחוויית בישול הטובה ביותר. בישול מהנה!', 'HUMAN', NOW() FROM description_blocks db WHERE db.recipe_id = 'f8c7c0e5-ed02-4070-8e8f-eb57e9f06e91' AND db.type = 'TEXT' AND db.text = 'Follow the detailed instructions below for the best culinary experience. Enjoy cooking!';
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '6e1b922a-11e5-433a-bf1a-37b245dcec34', 'he', 'פרסו את החצילים לעיגולים דקים. מלחו את הפרוסות כדי להוציא מהן נוזלים, ואז ייבשו אותן היטב במגבוני נייר או מגבת מטבח נקייה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '69e9de49-80a8-4f7c-8b5b-bacb474bc0eb', 'he', 'טגנו את פרוסות החציל בשמן רגיל עד להזהבה, ואז העבירו למגבוני נייר לסינון. אלטרנטיבה לאפייה: חתכו את הפרוסות לעובי של כ-1.5 ס״מ, מרחו כל אחת בשמן זית, ואפו ב-200 מעלות צלזיוס עד להזהבה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'e03f8bed-dfe4-4dc9-a616-9f5522782bbf', 'he', 'בקערה, ערבבו יחד שמן זית, מים קרים, חומץ, מיץ לימון, סירופ מייפל (או דבש או סילאן), שום קצוץ, פטרוזיליה קצוצה, מלח, פלפל ופפריקה. הניחו את תערובת הכבישה בצד ל-10 דקות.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '64eb32d3-4ec3-417a-bce3-d72c3fb6f894', 'he', 'סדרו את פרוסות החציל המטוגנות (או האפויות) בצורה מסודרת ושפכו את תערובת הכבישה בין השכבות. טעים במיוחד אחרי שעת מנוחה, ואפילו יותר טוב אחרי 4 שעות — אם כי אצלנו בבית זה בדרך כלל נגמר תוך 5 דקות!', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'b6b4dd30-e782-445a-9a6e-dff9ca1eeb9c', 'he', 'טגנו את משחת הקארי הירוק בשכבה עבה של חלב קוקוס עד שנפרש שמן ריחני.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'c75d6b6e-2ed3-4bf7-973f-48a39a89fdb5', 'he', 'הוסיפו את רצועות חזה העוף ובשלו עד שהשכבה החיצונית הופכת אטומה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '51e85316-a4c0-4dd6-a7f3-b5766e08ea6b', 'he', 'שפכו את יתרת חלב הקוקוס, החציל התאילנדי, רוטב הדגים וסוכר הדקלים, בשלו על אש נמוכה, וסיימו עם בזיליקום תאילנדי.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '99ff40ab-2193-4e27-906e-b98a0fbcb4b1', 'he', 'צלו את הג''ינג''ר והבצל, בשלו על אש נמוכה את עצמות מח הבקר יחד עם התבלינים הצלויים, כוכב אניס וקינמון בשקית תבלינים.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '9013c7d3-781f-4d09-831c-1e393524f2e6', 'he', 'הכשירו את אטריות האורז לפו במים רותחים, חלקו לקערות הגשה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'ad20bce1-b7d0-42ce-92d6-58c54b4182e5', 'he', 'סדרו על האטריות פרוסות בקר גולמי, יצקו מעל את המרק הרותח כדי לבשל את הבקר באופן מיידי, הגישו עם בזיליקום תאילנדי ונבטי שעועית.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'e0ac560e-6617-4bac-87aa-14efe48cb4ce', 'he', 'ערבבו את האורז המלא, הקינואה, העדשים האדומות ושעועית המש בקערה גדולה, כסו בנדיבות במים, והשרו יחד לילה שלם.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'ca338f4b-e7fe-442a-bb07-c603f92d80cc', 'he', 'בבוקר, סננו וטחנו הכול יחד עם כ-7 כוסות מים טריים לבלילה חלקה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'c9123450-96e4-4dda-a243-761fbf1e5b6a', 'he', 'העבירו את הבלילה לקערה או מיכל ותנו לה לתסוס בטמפרטורת החדר במשך כמה שעות.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'c0a0f437-669e-4911-8f31-a093abba7041', 'he', 'ערבבו פנימה מעט שמן זית ומלח לפי הטעם.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'caddfa4e-6120-429c-9fa3-2f7b2cb5f0a8', 'he', 'רפדו תבנית אפייה בנייר אפייה, מרחו קלות בשמן זית, ושפכו את הבלילה בשכבה דקה ואחידה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '17f62332-2953-40e1-8edf-b3127b083606', 'he', 'פזרו מעל זעתר, קצח, שומשום או זרעי כמון — לפי השילוב שאתם אוהבים.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'af371f98-a05c-45dd-b611-43ca9502a794', 'he', 'אפו כ-20 דקות ב-200–220 מעלות צלזיוס, עד שהתייצב והזהיב מעט.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '46c08304-7eb8-425a-bde1-b138c1154255', 'he', 'ציפו את סטייק טונת האהי בשומשום וצרבו במהירות במחבת לוהטת ל-45 שניות מכל צד.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '84751fa8-3512-487d-a5c2-d4667326bd86', 'he', 'פרסו את הטונה הצרובה לרצועות דקות נגד הסיבים.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '67aab39a-455f-4480-bf4e-741ef5c5655a', 'he', 'סדרו קערת אורז לסושי עם הטונה הצרובה, מנגו קצוץ, אבוקדו, וניגוב מיונז סריראצ''ה חריף.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '18ba72ea-a32e-4b28-a312-3bfa1f883c26', 'he', 'קלו את פרוסות המחמצת עד שמזהיבות ופריכות.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'e50586dc-fade-4c76-a7ae-5181bed63167', 'he', 'מעכו אבוקדו בשל עם מיץ לימון, מלח ופלפל שחור.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'c393470f-3326-45f2-918f-c9c52ce9ae70', 'he', 'פוצ''ו ביצים במים רותחים עם חומץ, מרחו את האבוקדו על הטוסט, הניחו מעל את הביצים, ופזרו פתיתי צ''ילי ותערובת תבלינים לבייגלים.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '1a619ef4-8119-4f92-9945-aff2c4892537', 'he', 'טחנו אסאי קפוא, תערובת פירות יער וחלב שקדים במהירות גבוהה עד לקבלת מרקם עבה וקרמי.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'd7707d6a-a324-40ad-8fb1-7ddba3fdd32b', 'he', 'העבירו את הסמוזי העבה לקערה רחבה וקרה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '22500f75-43bb-4fd9-95d0-8252834b6d53', 'he', 'סדרו פרוסות בננה, גרנולה וזרעי צ''יה בשורות מסודרות מעל.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '34bfb054-5325-4f73-95cb-ee9a49ad739d', 'he', 'השרו את ציר הדגים החם עם חוטי זעפרן ופפריקה מעושנת.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '612e4c5e-f927-4f97-a5f0-9030c674b49b', 'he', 'הכינו בסיס סופריטו במחבת הפאייה, הוסיפו את אורז הפאייה, ערבבו לציפוי, ושפכו את ציר הזעפרן בלי לערבב.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'bec4fd0a-c1f8-40a0-bb19-c153223a973c', 'he', 'שקעו את השרימפס והצדפות באורז ב-10 הדקות האחרונות ליצירת קרום סוקאראט פריך בתחתית.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'abd6e76d-4f17-4f17-bc3f-300b73c91d09', 'he', 'המיסו שוקולד מריר וחמאה מעל אמבט מים עד לקבלת מרקם חלק.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '2a9729bc-6452-4f26-ada8-60ad1f40b2d7', 'he', 'הקציפו ביצים ואבקת סוכר עד לקבלת מרקם עבה ובהיר, ואז קפלו בעדינות את תערובת השוקולד וקמח לבן רגיל.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'c4551233-6b8a-4487-b7b9-ea951dcd7616', 'he', 'שפכו לרמקינים משומנים ואפו ב-210 מעלות צלזיוס 12 דקות עד שהקצוות מוצקים והמרכז רך.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '9d9c1379-f064-4bff-9606-91079758a873', 'he', 'בשלו תפוחי אדמה לא קלופים עד שרכים בדיוק, פרסו לעיגולים עבים.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '6ddd3dd7-ddcd-4841-bc6c-40ef6ea289ba', 'he', 'טגנו את קוביות הבייקון והבצל בחמאה, דגלזו את המחבת ביין לבן.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '3a53e361-4c18-47f8-9a4f-0ab63b9a21ca', 'he', 'סדרו שכבות של תפוחי האדמה ותערובת הבייקון בתבנית אפייה, כסו בחצי גלגל רבלושון, ואפו ב-200 מעלות צלזיוס.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '6e39f938-4796-4086-af53-c5e147885567', 'he', 'צלו את חזה העוף המתובל, ואז פרסו לרצועות אלכסוניות.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '789542b4-6c3d-4929-a40e-a43f7c9cc5a3', 'he', 'קצצו את חסה הרומית וערבבו עם רוטב קיסר תוצרת בית בקערת עץ גדולה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '425ab3ec-242c-426b-b636-01d7f6e35f65', 'he', 'פזרו מעל את רצועות העוף הפרוסות, קרוטוני שום ומחמצת פריכים, ופרמזן מגורד דק.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'e42f9427-a7cf-4e69-b419-38acc4a102c4', 'he', 'השרו את קוביות העוף בשמן זית, מיץ לימון, שום ואורגנו למשך 30 דקות.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'e6ea2960-6700-4c7e-b412-b623f8cfe68f', 'he', 'השחילו את העוף על שיפודי עץ וצלו על אש גבוהה עד שחרוך ורך.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '68a705fe-dbc9-48eb-86d4-ab364d445513', 'he', 'הגישו את השיפודים חמים ישר מהאש לצד דיפ צזיקי קר ופיתה חמה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '8fd00411-928e-4838-b938-5df6c154f594', 'he', 'תבלו וטגנו במחבת את אומצות חזה העוף עד שמזהיבות משני הצדדים.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '356d7e76-5376-4584-8c67-2a8db60ba9aa', 'he', 'טגנו קלות את שיני השום ועגבניות מיובשות בשמש, ואז שפכו את השמנת המתוקה הסמיכה ובשלו על אש נמוכה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '78a5069a-aba5-4904-8342-36ee91a9b059', 'he', 'ערבבו פנימה תרד טרי עד שנובל, החזירו את העוף למחבת, וכפו את הרוטב מעל.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'eee9056d-4c22-4069-830a-270c868195c9', 'he', 'הביאו סיר גדול של מים מלוחים לרתיחה ובשלו את הספגטי עד למרקם אל דנטה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '7e440f98-368e-411b-820c-31d7a57f6f80', 'he', 'טגנו את הגואנצ''לה הפרוס במחבת על אש בינונית עד שמזהיב והשומן נמס.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '493a9116-a7a2-42fb-932a-b9d2bf727adb', 'he', 'הקציפו חלמוני ביצה עם פקורינו רומנו מגורר ופלפל שחור גרוס טרי עד לקבלת מרקם קרמי.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '2830cd00-629f-41a2-bda3-ab92f0e0b30a', 'he', 'השליכו את הפסטה החמה והמסוננת למחבת, הורידו מהאש, וערבבו במהירות את תערובת הביצים ליצירת אמולסיה מבריקה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '4fb6582a-9ed4-4c2a-bf6a-871097c06078', 'he', 'קרמלו לאט פרוסות בצל בחמאה עד שמזהיבות לעומק ומתוקות.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '914adcec-14ec-46ed-9856-829583eb371f', 'he', 'דגלזו את הסיר ביין לבן, הוסיפו ציר בקר, ובשלו על אש עדינה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '37edad87-2c89-42e5-b421-3a5fa35f6248', 'he', 'מזגו את המרק לרמקינים עמידים לתנור, כסו בבאגט קלוי וגרויר, וצרבו עד לבעבוע.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '4b8835b6-1246-4a5d-a9cd-a010d3abc5cc', 'he', 'טגנו את קוביות הבייקון עד שפריכות, צרבו את קוביות כתף הבקר המתובלות בשומן הבייקון עד להשחמה עמוקה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'a205ec4c-d8b2-4d7d-88ce-916132c8601d', 'he', 'שפכו יין אדום וציר בקר, כסו את הסיר, והעבירו לתנור ב-160 מעלות צלזיוס לבישול איטי.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '87bb38b6-e503-48be-8091-a3e4dfee18ef', 'he', 'טגנו בנפרד את בצלי הפנינה ופטריות הקרימיני בחמאה, ערבבו לתוך תבשיל הבקר ב-20 הדקות האחרונות.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '1181450d-c414-4b95-bbbe-82fc448cdd85', 'he', 'קצצו עגבניות ומלפפון לקוביות גדולות ופרסו בצל סגול דק.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '5a035fcd-047b-4c4f-acce-758fb3bf8d5d', 'he', 'ערבבו את הירקות וזיתי הקלמטה בקערה, זלפו בנדיבות שמן זית ואורגנו בר.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'a77aa00d-e96e-4205-8e21-b6187153daca', 'he', 'הניחו מעל קובייה שלמה של גבינת פטה והגישו קריר עם לחם פריך.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '9f42c432-63ec-46a0-ba64-b1cc3a49206a', 'he', 'טחנו את גרגירי החומוס המושרים, פטרוזיליה, כוסברה, שום ותבלינים במעבד מזון עד לקבלת תערובת גסה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '5b1754df-1296-4927-b9bb-458061f80614', 'he', 'עצבו כדורי פלאפל וטגנו בשמן עמוק עד להזהבה עמוקה ופריכות.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'e0b89fbd-261b-46ea-a741-98446003e8db', 'he', 'הקציפו את הטחינה עם מיץ לימון ומים קרים, מלאו את הפיתות בפלאפל ובסלט ישראלי, וזלפו מעל את הטחינה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '3ef99f5b-1e1a-485e-a1ee-11dd369d2dd8', 'he', 'סדרו קוביות בריוש בתבנית אפייה משומנת בגודל 23x33 ס״מ.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'd05f4bc7-af35-45d6-9a11-a3344f771cac', 'he', 'הקציפו ביצים, חלב, שמנת מתוקה סמיכה, סוכר חום וקינמון טחון; שפכו באופן אחיד מעל קוביות הבריוש.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '833a3f63-2d3e-4d18-85c2-ab3f65b55641', 'he', 'אפו ב-180 מעלות צלזיוס עד שתפוח ומוזהב, ואז זלפו בנדיבות גלייז גבינת שמנת חם.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'df4a5754-a483-407f-a964-8a7bcb73fe8f', 'he', 'חממו את שמן הזית בסיר על אש גבוהה. הוסיפו את הפלפל החריף והפלפלים, וכסו במכסה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '52e0c051-6e0c-49ec-afb1-d776395a4426', 'he', 'כשמתחיל להדיף ריח, הפכו את הפלפלים לצד השני והנמיכו את האש.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'c6697d48-44fa-4798-ab06-9729603d13de', 'he', 'הוסיפו את העגבניות, השום, הפפריקה והכוסברה. בשלו על אש נמוכה 30 דקות, ואז הוסיפו קציצות דגים או חתיכות דג.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'e5e76602-0a9a-460b-9af5-9a759f1f0762', 'he', 'הקציפו חלמוני ביצה, חלב, קמח עוגות ואבקת מאצ''ה יחד לבלילה חלקה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '4d9dd0f5-8bf3-403f-8dbb-a53892a7dd8a', 'he', 'הקציפו חלבוני ביצה עם סוכר למרנג יציב ומבריק.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '312d8d38-36c8-4234-b065-c89ac8349b31', 'he', 'קפלו בעדינות את המרנג לתוך הבלילה, הניחו ערימות גבוהות על מחבת נון-סטיק, כסו ובשלו על אש נמוכה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'af642160-0400-4a53-9e7b-bec8681fba3d', 'he', 'בשלו על אש נמוכה את עגבניות סן מרצאנו הקלויות עם שום ועשבי תיבול, ואז טחנו חלק עם שמנת מתוקה סמיכה ובזיליקום טרי.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'b3906ec5-fb78-4c51-848b-5c960d6babe2', 'he', 'מרחו חמאה בנדיבות על החלק החיצוני של פרוסות המחמצת, ומלאו ביניהן צ''דר חריף.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'd28d9c68-a484-489a-a9be-bf6d99d4bb1a', 'he', 'צלו את הכריך במחבת על אש בינונית-נמוכה עד שהקרום מוזהב לעומק והגבינה נמסה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'dded2852-7689-4d37-a6e0-b8dd54332898', 'he', 'צרבו את ירכי העוף עם צד העור כלפי מטה במחבת לוהטת עד שפריך ומוזהב.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'ed153176-5f56-44b9-9b68-8820305b5122', 'he', 'שפכו רוטב סויה, מירין, סאקה ודבש, בשלו על אש נמוכה עד שהרוטב הופך לגלייז דביק ועבה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '5ab5eea7-b741-4c2e-a061-1989ec1187ae', 'he', 'פרסו את העוף, הניחו מעל אורז יסמין מאודה עם ברוקולי, וזלפו בנדיבות את רוטב הטריאקי.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '384f8b00-92ec-4477-9a5c-1642824f4509', 'he', 'סדרו את פילה הסלמון והאספרגוס על תבנית אפייה מרופדת בנייר אפייה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '08b11c40-6d14-46d6-ba7c-ffd13a292c3c', 'he', 'מרחו את הסלמון בחמאת שום, תבלו במלח, פלפל ופרוסות לימון.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'ffcf5a10-2174-4727-922b-e77cc812f4fb', 'he', 'אפו בתנור מחומם מראש ל-200 מעלות צלזיוס עד שהסלמון מתפרק בקלות עם מזלג.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '0920b8c8-095a-435a-82df-8e1870a930b9', 'he', 'הכינו את הבצק: שפכו את הקמח, הסוכר והשמרים לקערת ערבוב וערבבו יחד. עשו גומה במרכז ושפכו פנימה את שאר מרכיבי הבצק (שמן, מים, חלב צמחי, מלח). ערבבו הכול בכף או בספטולה עד לתערובת אחידה למדי — היא לא תהיה חלקה כמו בצק לָשׁ, אבל הכול אמור להתאחד; זה בסדר.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'd8054d7c-22bd-4fe9-809e-9915b97fda86', 'he', 'תפיחה ראשונה: כסו את הקערה ותנו לה לתפוח בטמפרטורת החדר במשך 2–4 שעות. (לחלופין: השאירו בחוץ 15 דקות, ואז קררו במקרר ל-8–24 שעות — הוא אולי לא יכפיל את עצמו לגמרי, אבל יהיה קל יותר לעבוד איתו. לתפיחה מהירה יותר, הניחו בתנור כבוי או במצב הכי נמוך עם קערת מים רותחים בתחתית, שמתפיחה תוך כ-45 דקות — אבל הוא יהיה רך ודביק מדי לריפוד, אז קררו בפריזר 15 דקות לפני העיצוב.)', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '97f9e56e-48d9-4430-8e2e-92f1ca148c4b', 'he', 'הכינו את מילוי השוקולד: שקלו את מרכיבי מילוי השוקולד — חוץ מהשוקולד הקצוץ — לקערה ומיקרוגלו כ-30 שניות עד דקה, תוך ערבוב עד שנמס לגמרי. קררו במקרר כ-20 דקות עד שנמרח (הקצוות החיצוניים עשויים להתקשות מהר יותר מהמרכז — ערבבו היטב וקררו עוד מעט אם צריך).', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'ca50607c-d86e-40d7-921a-32d3df364449', 'he', 'הכינו את הסירופ: המיסו יחד מים וסוכר בסיר קטן; כבו את האש ברגע שכל הסוכר נמס (ערבבו קצת ברגע שהוא מתחיל להתמוסס).', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '60f5bae8-bc5b-469e-a960-dfeb05579576', 'he', 'עבדו את הבצק: לאחר התפיחה הראשונה, קמחו את משטח העבודה, את הבצק ואת הידיים. הפכו את הבצק על המשטח המקומח. משכו את הבצק מהצדדים ומהתחתית כלפי מעלה למרכז העליון, שוב ושוב, וקמחו מחדש את המשטח ככל שנחשף, עד שהבצק פחות דביק וקצת חלק יותר. חלקו לשניים; החזירו חצי לקערה וכסו אותו.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '7cd13e40-d61f-4c17-b6ec-911016388b13', 'he', 'רדדו ומלאו את החצי הראשון: עבדו מעט יותר את החצי הראשון של הבצק. קמחו שוב את משטח העבודה, הניחו את הבצק במרכז, וקמחו את החלק העליון. רדדו למלבן בעובי של כ-0.5 ס״מ (המשיכו לקמח למעלה ולמטה כדי שלא ידבק — בצק ללא לישה דביק יותר מבצק שמרים קלאסי, וזה מה ששומר עליו עביד). מרחו כמחצית ממילוי השוקולד על פני כל המלבן. קפלו בסגנון מעטפה: הורידו את הקצה העליון כלפי התחתון, אך לא עד הסוף, ואז הרימו את הקצה התחתון מעל לעליון. רדדו את הבצק המקופל לכמחצית מעוביו (זה בסדר אם קצת מילוי נסחט החוצה או שהחלק העליון נקרע מעט). מרחו את יתרת מילוי השוקולד על הבצק, השאירו קצה אחד נקי, ואז פזרו מעל את השוקולד הקצוץ. גלגלו את הבצק לכיוון הקצה הנקי (הרטיבו את הקצה מעט באצבע כדי לעזור לאיטום). חתכו את הגליל המגולגל לאורכו לשניים, סובבו את שני החצאים כך שהצד החתוך פונה כלפי מעלה, ואז פתלו אחד מעל השני ליצירת פיתול קלוע. העבירו בזהירות לתבנית האפייה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '61532c9b-31b0-4fba-a34f-3093b267bb69', 'he', 'תפיחה שנייה: כסו ותנו לתפוח בטמפרטורת החדר במשך 30–40 דקות, עד שהנפח מכפיל את עצמו.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '016f53fb-c311-41f3-9536-7c642f8a4f97', 'he', 'חזרו עם החצי השני: חזרו על שלבים 6 ו-7 עם החצי השני של הבצק. הפעם, מרחו חמאת בוטנים על המלבן המרודד הראשון, ולאחר הקיפול והריפוד מחדש, מרחו את הריבה מעל לפני הגלגול, החיתוך והפיתול כמו קודם.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'b656c72e-15a2-403b-bed0-4ab6e6bff727', 'he', 'חממו מראש את התנור ל-180 מעלות צלזיוס (טורבו/מאוורר). מרחו את הכיכרות במעט חלב צמחי. אפו כ-35 דקות, עד להשחמה יפה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '1886d866-7f8f-4bb5-b4c7-d7522461e172', 'he', 'ברגע שהכיכרות יוצאות מהתנור, מרחו אותן בנדיבות בסירופ הסוכר — אל תחכו.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '881163e9-cd9d-4844-99ed-dfec4077eb26', 'he', 'מתחו את בצק הפיצה ביד לדיסקית דקה בקוטר 30 ס״מ עם שפה מוגבהת בהיקף.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '525e76f5-1913-4f8b-a515-473b515d6bdc', 'he', 'מרחו קלות עגבניות סן מרצאנו מרוסקות, הוסיפו חתיכות מוצרלה טרייה קרועות.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'eb3cc9c0-f5e4-4edb-89b7-43ebfff3fa19', 'he', 'אפו על אבן פיצה מחוממת מראש ב-250 מעלות צלזיוס (או בתנור עצים) עד שהבצק מבועבע, ואז סיימו עם בזיליקום טרי וזילוף שמן זית כתית מעולה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'd0b38cb0-8197-4b1c-9aed-e861f67b85c5', 'he', 'צרבו את ירכי העוף המושרות במחבת לוהטת או בגריל התנור עד שחרוכות קלות.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'c8294eee-b5b7-430f-8168-8dd73da4ad01', 'he', 'בשלו על אש נמוכה את רסק העגבניות עם חמאה, שמנת מתוקה סמיכה, גראם מסאלה ועלי חילבה עד לקבלת מרקם חלק ומשיי.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'a0319102-dbc5-4a03-8fb9-3c315552b92f', 'he', 'שלבו את העוף לתוך הרוטב, בשלו על אש נמוכה 5 דקות, קשטו בשמנת והגישו עם נאן חם.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '62baa50b-dae5-48df-9e9f-cecde00ec16c', 'he', 'השרו במים את פלפלי הגוואחילו והאנצ''ו היבשים, טחנו עם שום ותבלינים, והשרו בהם את כתף הבקר.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'e5e6c8db-c904-4f9b-b2e0-999e24e5573a', 'he', 'בשלו על אש נמוכה את כתף הבקר בציר בקר עד שרך ונמס בפה, ואז קרעו לחוטים דקים.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '5832cbd3-aa9b-4c31-9bae-f4dd7bb50435', 'he', 'טבלו את טורטיות התירס בקונסומה, מלאו בגבינת אוואחקה ובקר קרוע, קפלו וטגנו עד לפריכות.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '23d12579-a80b-465f-a494-2e75abf8ff82', 'he', 'טגנו פלפל אדום קצוץ, בצל ושיני שום קצוצות בשמן זית עד שרכים.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '34c1dc7d-0637-4d17-a72d-655a09d2962a', 'he', 'הוסיפו עגבניות קצוצות, כמון ופפריקה מעושנת. בשלו על אש נמוכה עד שהרוטב מתעבה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '61ef2686-dbd8-4d50-b5c0-4e33d42b22b2', 'he', 'צרו גומות קטנות ברוטב, שברו פנימה את הביצים, כסו, ופוצ''ו בעדינות עד שהחלבון מתייצב. סיימו בפיזור פטה מפוררת.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'b20e1f82-bf42-4293-a2e3-35168ccc577e', 'he', 'חממו מראש את התנור ל-160 מעלות צלזיוס.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '2c7dbd00-9d6f-4d62-ab18-ecc6b799e7ad', 'he', 'ערבבו את כל המרכיבים בקערה, לפי הסדר הרשום, וערבבו היטב בכף עד שכל הקמח נספג לגמרי בבלילה. הבלילה אמורה לצאת די נוזלית — זה תקין, כך היא צריכה להיות.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '0d8ca09c-58c9-4573-9a3a-4cc361600372', 'he', 'שפכו מחצית מהבלילה על תבנית אפייה מרופדת בנייר אפייה ופזרו באופן אחיד עד שהנייר מכוסה לגמרי. הכמות הזו מספיקה בדיוק לשתי תבניות תנור סטנדרטיות, אז אם נגמר לכם לפני שכיסיתם את התבנית, פזרו דק יותר.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '93aadd34-184d-4b21-8296-f8305ad91382', 'he', 'אפו 30 דקות, ואז הפכו את התבנית.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'd0268048-3f6f-48eb-8d9d-04fff33f0069', 'he', 'המשיכו לאפות עוד 30 דקות, או עד שמזהיב לעומק ופריך לגמרי. אם השכבה לא נפרשה בעובי אחיד, חלקים מסוימים יסתיימו לפני אחרים — בדקו באופן קבוע וודאו שאופים עד שהכול פריך לגמרי.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'd422d0de-2542-40ea-9971-187f07d5f3fe', 'he', 'הוציאו מהתנור, תנו להתקרר מעט, ואז שברו בחופשיות לקרקרים. אם זה לא נשבר בנקישה נקייה ופריכה, החזירו לתנור לכמה דקות נוספות.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'e3d2fa77-6395-45b5-b185-33429a301359', 'he', 'בקערה גדולה, ערבבו יחד את הקמח, הסוכר והשמרים היבשים. הוסיפו את הביצה, השמן והמים הפושרים, וערבבו בכף עד שהתערובת מתחילה להתאחד. (חלופה: במקום שמרים יבשים, פוררו 25 גרם שמרים טריים לקערה קטנה עם כף אחת מהסוכר, הוסיפו מחצית מהמים, ערבבו, והשאירו 10-15 דקות עד שמקציף, ואז ערבבו לתוך הקמח עם שאר הסוכר, הביצה, השמן והמים.)', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'eccf9292-7d21-4dd4-8293-cc3d518dad6d', 'he', 'לושו ביד 3-4 דקות (או השתמשו במיקסר עומד עם וו לישה). אם הבצק דביק, הוסיפו מעט קמח נוסף; אם יבש מדי, הוסיפו קצת מים.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'c607cf01-03be-465e-8fef-34a00707e5f9', 'he', 'פזרו את המלח באופן אחיד מעל הבצק והמשיכו ללוש עוד 4-5 דקות, עד שהבצק חלק ואחיד.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '9a6475f4-aa03-43ad-9f3b-8dc64d9c8a77', 'he', 'כסו את הקערה במגבת ותנו לבצק לתפוח במקום חמים למשך שעה עד שעה וחצי, עד שהנפח מכפיל את עצמו.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'a3c1d6da-a2dd-413d-a339-00d5c3875da0', 'he', 'על משטח מקומח קלות, חלקו את הבצק ל-4 חלקים שווים ורדדו כל חלק לרצועה ארוכה של כ-55-60 ס״מ.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '1fc6a1cb-d8ad-4e83-8f21-357e944f95d7', 'he', 'פתלו שני רצועות יחד בדפוס ''ברגית'' רופף, ואז כרכו לספירלה (כמו קונכיית שבלול) — שמרו על רפיון, לא הדוק מדי, כדי שלחלה יהיה מקום לתפוח. חזרו עם שתי הרצועות הנותרות לעיצוב החלה השנייה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'a095bcfd-b364-4c27-81e9-0ea78a415b6f', 'he', 'רפדו תבנית אפייה בנייר אפייה והניחו עליה את החלות המעוצבות. כסו במגבת ותנו לתפוח שוב במקום חמים למשך כשעה עד שעה וחצי, עד שהנפח מכפיל את עצמו.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '17fa808a-64bc-4ac4-b41e-a824e6238e4e', 'he', 'מרחו את החלות במשיחת ביצה (ביצה טרופה אחת מעורבבת עם כפית שמן) ופזרו שומשום.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '84b47ea3-bbfe-43a8-ae69-8a31fef51d51', 'he', 'חממו מראש את התנור ל-180 מעלות צלזיוס למשך 7 דקות לפחות. כשהתנור חם, אפו את החלות כ-30 דקות, עד להזהבה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '5a6fa535-590c-47f9-a17b-4e34b8839886', 'he', 'ציפו את קוביות הטופו בעמילן תירס ושמן שומשום, טגנו במחבת עד לפריכות בכל הקצוות.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '5584ed48-6b80-4da9-9561-fc72aa87338d', 'he', 'הקציפו חמאת בוטנים, רוטב סויה, סירופ מייפל, ג''ינג''ר מגורר ומים חמים לרוטב חלק.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'a6ed24d5-907a-422d-a47b-f968ab94325b', 'he', 'הרכיבו קערת קינואה עם אדממה, גזר, טופו פריך, וזלפו בנדיבות ברוטב הבוטנים.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'f573569a-200e-4ec5-88e0-9f2cf2a71d2d', 'he', 'טגנו פרוסות פטריות בר בשמן זית עד להזהבה, שימרו מחצית בצד לקישוט.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'e151c599-481c-4626-bd5f-d9c11a7b522a', 'he', 'קלו את אורז הארבוריו בשמן שאלוט, דגלזו ביין לבן, ואז הוסיפו את ציר הירקות מצקת אחר מצקת תוך ערבוב מתמיד.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '01ba520f-71bd-4639-8201-e5a36d8dcf5f', 'he', 'הורידו מהאש, ערבבו פנימה חמאה, פרמג''אנו-רג''אנו ותערובת הפטריות עד לקבלת מרקם מבריק.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'c17809c9-59bd-4aca-bab2-956311041a17', 'he', 'לחצו את פירורי הביסקוויטים החמאתיים והחמאה בחוזקה לבסיס תבנית ספרינגפורם ואפו מראש את הבסיס.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '0782971d-d0d4-4c97-84bd-017b6b1cb804', 'he', 'הקציפו גבינת שמנת וסוכר עד לחלקות מוחלטת, ערבבו פנימה שמנת חמוצה, שמנת מתוקה סמיכה וביצים אחת אחרי השנייה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'd7722bb7-119a-4ccb-ba40-263ab33481cd', 'he', 'אפו את עוגת הגבינה באמבט מים ב-160 מעלות צלזיוס, קררו לאט בתוך התנור הכבוי כדי למנוע סדקים.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '95de1696-8402-4ee0-9bb1-bca5eda8fbcd', 'he', 'חממו את טורטיות התירס בשמן עד שגמישות, מרחו מעליהן את השעועית השחורה המרוסקת והחמה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', 'da3cae0c-123d-4bad-9fc9-9d8547c3b48c', 'he', 'טגנו את הביצים בסגנון עין בשמן עד שהקצוות פריכים והחלמון נוזלי.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '9fcc19b5-a42e-4f36-9bc0-600d8d170c50', 'he', 'הניחו את הביצים מעל טורטיות השעועית, כפו מעל את סלסת הראנצ''רו הקלויה החמה, וקשטו באבוקדו וגבינת קוטיחה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '20f7b19e-cafd-4c1b-84f7-bda25db2a88e', 'he', 'חלקו את הבקר הטחון לשני כדורים ומעכו שטוח על מחבת ברזל יצוק לוהטת.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '4ec43891-cb9a-4631-8399-18bbf2ee31b5', 'he', 'הפכו את הקציצות, הניחו מעל גבינה אמריקאית, ותנו להימס עד שהקרום כהה והגבינה נמסה ונמתחת.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INSTRUCTION_TEXT', '95b218e9-952d-4b68-a759-1215e849f4b7', 'he', 'מרחו את הרוטב הסודי על בריוש קלוי בחמאה, הוסיפו את הקציצות והחמוצים, והגישו מיד.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INGREDIENT_NAME', '387f63b9-93e7-40ad-9e1f-9d3d47f9c39b', 'he', 'סירופ מייפל, דבש, או סילאן', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'INGREDIENT_NAME', '7ed306fe-956e-415f-8a12-4ec66c19cfc6', 'he', 'חומץ', 'HUMAN', NOW());
