INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'UNIT_NAME', 'f4b1b9c0-7771-4231-a0c2-cdff2bcd5f70', 'he', 'פרוסה', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'UNIT_NAME', 'f5a82f9a-438c-4f64-b234-19d4da3fc54a', 'he', 'חופן', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '0ea015b7-a69e-4e93-a9c5-874f06a047b4', 'he', 'סלט חצילים כבושים מזרח תיכוני תוסס: פרוסות חציל דקות מטוגנות (או אפויות) עד להזהבה, ואז מסודרות בשכבות עם כבישה של שמן זית עם שום, חומץ ולימון, עמוסה בפטרוזיליה טרייה. הכי טוב אחרי שעות מנוחה, אבל לרוב לא שורד כל כך הרבה זמן.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '142c152b-0fff-4133-9f1c-564da0b5b411', 'he', 'קארי חלב קוקוס ריחני עם רצועות עוף רכות, חציל תאילנדי, נבטי במבוק, ועלי בזיליקום תאילנדי מתוק וטרי.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '1868adb5-a11b-43d8-aece-e84db8fa2110', 'he', 'מרק עצמות בקר מתובל וריחני שמתבשל 12 שעות, מוגש על אטריות אורז, פרוסות דקות של בקר גולמי (Eye Round), בזיליקום טרי ונבטי שעועית.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '20d15ac3-a89c-4115-ba21-2d3447105f38', 'he', 'לחם שטוח ללא גלוטן העשוי מאורז, קינואה, עדשים ושעועית מש שהושרו והותססו — נטחנים לבלילה, נאפים דק, ומתובלים בזעתר, קצח, שומשום או זרעי כמון. לא באמת פיתה, אלא תחליף מזין ועתיר חלבון.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '261a09eb-c028-43e0-ae38-5f815ff96e67', 'he', 'טונה אהי צרובה בציפוי שומשום מעל אורז לסושי עם מנגו, מלפפון, אדממה, אבוקדו וניגוב מיונז סריראצ''ה חריף.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '26b0c2da-12dd-4e64-a871-a65dc70ad6c7', 'he', 'פרוסת מחמצת קלויה עם אבוקדו מרוסק ולימון, מוגשת עם ביצה פושה נוזלית, צנוניות ופתיתי פלפל אדום.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '2bb704e1-955d-4c0a-bfc5-25e3fc2872ef', 'he', 'תערובת עבה ותוססת של אסאי קפוא ופירות יער, מתובלת בזרעי צ''יה, פרוסות בננה, שבבי קוקוס קלויים וגרנולה פריכה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '2ccb4de6-3b95-437d-a540-37ade62e0be1', 'he', 'אורז זעפרן ולנסיאני מסורתי עם שרימפס ג''מבו, צדפות, טבעות קלמארי, פלפלים אדומים ואפונה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '31835cec-ba46-452c-a2d2-1e69502481f6', 'he', 'עוגיות שוקולד מריר עשירות עם מרכז שוקולד נוזלי חם, מפוזרות באבקת סוכר וגלידת וניל.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '3c1e26ca-59fa-408a-8df2-bc408fba42ab', 'he', 'תבשיל אלפיני צרפתי עשיר של תפוחי אדמה פרוסים, קוביות בייקון מעושנות ובצל מקורמל, מכוסה בגבינת רבלושון מומסת.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '484d779c-dbaf-4e82-b7d5-c7e5f51bf6da', 'he', 'לבבות חסה רומית פריכים בתוספת רוטב קיסר קרמי עם אנשובי ושום, קרוטוני שום ומחמצת פריכים, פרמזן מגורד דק ועוף על האש.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '4f8814b2-893c-454f-bf75-eca536395fdc', 'he', 'שיפודי עוף רך שהושרה ברוטב לימון ועשבי תיבול, נצלה מעל להבה, מוגש עם רוטב צזיקי מלפפון קריר ופיתה תפוחה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '5ceed62f-4bfc-4721-a10c-a33673c61e0d', 'he', 'חזות עוף מוזהבות מטוגנות במחבת, מבושלות ברוטב שום קרמי ועשיר עם עגבניות מיובשות בשמש ותרד טרי.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '5ddf22a1-3236-40fa-95c7-fc7c12ecfab5', 'he', 'פסטה קרבונרה רומית אותנטית עם גואנצ''לה פריך, חלמוני ביצה, גבינת פקורינו רומנו מגוררת טרייה ופלפל שחור גרוס.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '680f62e8-efc9-4fb9-a45a-e6686a90fc06', 'he', 'בצל צהוב מקורמל לעומק ומבושל בציר בקר ויין, מכוסה בפרוסות באגט קלויות וגבינת גרויר מומסת.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '6fec851f-ad5d-4b81-ab58-cdf6b8979dc7', 'he', 'התבשיל הצרפתי האיקוני של ג''וליה צ''יילד עם כתף בקר רכה המבושלת לאט ביין בורגונדי אדום עם בצלי פנינה, קוביות בייקון ופטריות.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '731fa47b-2776-4673-8808-729bdb4e3491', 'he', 'מלפפונים פריכים, עגבניות שרשרת בשלות, בצל סגול, זיתי קלמטה, ופרוסת גבינת פטה יוונית קרמית, מוגשים בשמן זית כתית מעולה ואורגנו.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '7f2a0505-0cc3-477d-9a36-df0064c3a65b', 'he', 'פלאפל חומוס פריך ומוזהב במילוי פיתה חמה ותפוחה, עם סלט ישראלי קצוץ, חמוצים וטחינה עשירה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '8c71e60f-34cb-43ad-a40e-6f168c39fccc', 'he', 'תבשיל בריוש קוביות תפוח ורך, טבול ברביכת ביצה וקינמון, נאפה עד להזהבה ומכוסה בגלייז גבינת שמנת ואגוזי פקאן קלויים.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '8dc69d68-9011-496c-a78f-527963757ed6', 'he', 'צ''ריימה של איציק — רוטב עגבניות חריף בסגנון צפון אפריקאי המבוסס על שום, כוסברה, פפריקה ופלפלים מתוקים, מתבשל עד שמתעבה ועשיר, ומסתיים עם קציצות דגים או דג המתבשל ישירות ברוטב.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '9e3c9378-18b9-4a9b-9437-fa1934578333', 'he', 'פנקייקים סופלה גבוהים במיוחד, אווריריים ותפוחים, עם אבקת מאצ''ה איכותית מאוג''י, מוגשים עם קצפת וסירופ מייפל.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', '9fce3441-ee40-4db8-927c-ce9f5aeb1a3e', 'he', 'מרק עגבניות ובזיליקום קלוי ועשיר, מוגש לצד כריך גבינה מחמצת מוזהב וחמאתי עם צ''דר נמס.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', 'a55beba1-f52d-41cb-9e37-d2f19730654b', 'he', 'ירכי עוף רכות מטוגנות במחבת ומצופות ברוטב טריאקי דביק תוצרת בית, מוגשות מעל אורז מאודה תפוח וברוקולי מאודה.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', 'a6715a57-d460-4930-b4f4-fe3b39ed0533', 'he', 'פילה סלמון צלוי בתנור עם קרום חמאת שום מוזהב, שמיר טרי ואספרגוס צלוי.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', 'adefaece-50fb-439d-816a-2790342c7d1d', 'he', 'עוגת קרנץ שמרים מגולגלת ומפותלת — כמו בבקה — העשויה מבצק ללא לישה שלא מסבך. במקום בצק מודבק אמיתי, הבצק מרודד וממולא פעמיים כדי לבנות שכבות דקות עם הרבה מילוי, ואז מפותל לצמה ונאפה. המתכון הזה מכין שני כיכרות: אחת עם מילוי שוקולד עשיר, והשנייה עם חמאת בוטנים וריבה, שתיהן נמרחות בסירופ סוכר ישר מהתנור.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', 'b09fecbd-68a8-4185-968f-14bf9982b980', 'he', 'פיצה נפוליטנית קלאסית בעלת בצק דק, מכוסה ברוטב עגבניות סן מרצאנו, מוצרלה די בופאלה טרייה ועלי בזיליקום מתוקים וריחניים.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', 'b9eb0d23-96e4-46fc-bd90-240d242dc5d4', 'he', 'חתיכות עוף רכות שהושרו ביוגורט מתובל, מבושלות ברוטב עגבניות עשיר, שמנת, חמאה וגראם מסאלה, עם נאן חם.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', 'beeb351d-3977-45f6-ae2d-045c23ca1672', 'he', 'בקר קרוע רך שמתבשל לאט במרק פלפלי גוואחילו-אנצ''ו עשיר, ממולא לתוך טורטיות תירס עם גבינת אוואחקה נמסה וצרוב עד לפריכות.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', 'c15e7c29-b6ed-4728-a652-4321527abf64', 'he', 'ביצים פושה ברוטב עגבניות, פלפלים ושום עשיר ומבושל, מתובל בכמון ופפריקה מעושנת, מכוסה בפטה מפוררת.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', 'd6162e6e-1ce4-4a5e-91d1-6754926f814d', 'he', 'קרקרים ללא גלוטן העשויים משיבולת שועל וזרעים — פשוטים להכנה, פריכים להפליא, ונשמרים היטב בכלי אטום עד שבועיים.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', 'd63b981b-1417-4b97-8c13-3f767398858a', 'he', 'חלת שבת קלה, אווררית וטעימה, בהדרכה שלב אחר שלב. היא דורשת קצת יותר מאמץ ממתכון מהיר טיפוסי, אבל נשארת פשוטה וניתנת לניהול — והגרסה עם שמרים טריים יוצאת קלילה וטעימה במיוחד.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', 'd6802a63-c533-4681-990e-bb64664db63b', 'he', 'קוביות טופו שומשום פריכות מוגשות מעל קינואה עם כרוב סגול, אדממה, גזר מגורר ורוטב בוטנים-ג''ינג''ר קרמי.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', 'de2d322c-e552-4016-8539-a12dbb718832', 'he', 'אורז ארבוריו איטלקי המבושל לאט תוך ערבוב בציר ירקות טעים, מסתיים בפטריות פורצ''יני מוקפצות, חמאה ופרמג''אנו-רג''אנו.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', 'e09a50a9-ffd9-4983-b75d-4a7877bdd78c', 'he', 'עוגת גבינה אפויה סמיכה וקרמית במיוחד עם בסיס פירורי ביסקוויטים חמאתי, נאפית לאט ומכוסה ברוטב פטל טרי.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', 'f5a9c699-8b80-490f-83f6-b47aa957df46', 'he', 'טורטיות תירס חמות מכוסות בביצים מטוגנות עין, סלסת ראנצ''רו עגבניות קלויות תוצרת בית, שעועית מרוסקת ואבוקדו.', 'HUMAN', NOW());
INSERT INTO content_translations (id, entity_type, entity_id, locale, value, source, updated_at) VALUES (UUID(), 'RECIPE_DESCRIPTION', 'f8c7c0e5-ed02-4070-8e8f-eb57e9f06e91', 'he', 'שני קציצות בקר מעוכות ופריכות, גבינה אמריקאית נמסה, בצל מקורמל, חמוצים ורוטב המבורגר ביתי עשיר על בריוש קלוי.', 'HUMAN', NOW());